from format_lecon import table,paras
DIAGNOSTICS=[
('Angio-œdème histaminergique','Minutes à heures, urticaire ou prurit possibles.','Rechercher anaphylaxie et atteinte des voies aériennes.','Évaluation clinique ; bilan allergologique orienté après sécurisation.','🚩 E1 si anaphylaxie ou atteinte laryngée.'),
('Angio-œdème associé aux inhibiteurs de l’enzyme de conversion','Gonflement sans urticaire, traitement en cours parfois ancien.','Langue et voies aériennes ; ne pas exclure sur longue tolérance antérieure.','Histoire médicamenteuse et exclusion des autres mécanismes.','🚩 E1 si menace respiratoire.'),
('Angio-œdème héréditaire','Crises récurrentes sans urticaire, parfois abdominales.','Atteinte laryngée et histoire familiale, parfois absente.','C4 et quantité/fonction du C1-inhibiteur, expertise spécialisée.','🚩 E1 pour toute atteinte potentielle des voies aériennes.'),
('Abcès odontogène','Douleur dentaire, tuméfaction faciale et foyer buccal.','Trismus, plancher buccal, extension cervicale ou systémique.','Examen dentaire et imagerie adaptée.','🚩 E1 si extension profonde ou sepsis.'),
('Sialolithiase','Tuméfaction salivaire douloureuse rythmée par les repas.','Rechercher surinfection et obstruction.','Échographie puis examens ciblés selon localisation.','E2 si infection associée ou obstruction importante.'),
('Infection cervicale profonde','Fièvre, odynophagie, torticolis ou trismus.','Stase salivaire, dysphonie, dyspnée, plancher induré.','Imagerie injectée après sécurisation et avis chirurgical.','🚩 E1 si menace respiratoire, sepsis ou extension.'),
('Adénite cervicale infectieuse','Ganglion douloureux dans un contexte infectieux.','Suppuration, extension et persistance inexpliquée.','Examen du territoire drainé ; biologie et échographie ciblées.','E2 ; E1 si complication profonde ou systémique.'),
('Goitre','Masse antérieure thyroïdienne, parfois ancienne.','Dysphagie, dysphonie ou dyspnée compressives.','TSH, échographie et bilan complémentaire orienté.','E2 ; E1 en cas de compression respiratoire aiguë.'),
('Adénopathie cervicale maligne','Masse persistante, progressive, parfois indolore ou kystique.','Lésion muqueuse, signes généraux et autre localisation.','Examen spécialisé, imagerie et prélèvement approprié.','E2, accéléré si progression ou compression.'),
('Syndrome de la veine cave supérieure','Œdème cervicofacial, parfois membres supérieurs et veines collatérales.','Dyspnée, signes neurologiques, cathéter ou cancer.','Imagerie veineuse thoracique adaptée.','🚩 E1 si atteinte respiratoire ou neurologique.')]
ACTIONS=['Traiter une anaphylaxie sans délai ; antihistaminique selon le tableau cutané isolé.','Arrêter le médicament et sécuriser les voies aériennes selon la gravité.','Traiter précocement selon le plan spécialisé et surveiller toute atteinte laryngée.','Drainer et traiter la dent ; antibiothérapie selon diffusion et contexte.','Prendre en charge l’obstruction et une surinfection éventuelle.','Hospitaliser, contrôler le foyer et administrer une antibiothérapie adaptée.','Traiter la cause et organiser la réévaluation ; drainer une suppuration si indiqué.','Surveillance ou intervention selon fonction, compression et bilan.','Organiser un diagnostic tissulaire et le traitement oncologique adapté.','Traiter thrombose ou compression avec l’équipe spécialisée.']
def comparison():
 return paras('Ces dix diagnostics structurent la démarche. Leur ordre est pédagogique : aucune série suisse comparable ne permet ici de les classer par prévalence. La liste n’est pas exhaustive et la priorité dépend des signes de gravité.', 'E1 signifie une évaluation immédiate d’une menace ; E2 indique une évaluation rapide adaptée au contexte. Ces repères pédagogiques ne constituent pas un score validé.')+table(['Diagnostic','Profil','Élément discriminant','Confirmation orientée','Conduite','Priorité'],[[f'DX.{i} — '+row[0],*row[1:4],ACTIONS[i-1],row[4]] for i,row in enumerate(DIAGNOSTICS,1)])
